    internal static int CtCountPage(emon.Port.Cells gl, int page) {
        int n = Evidence.GlCount(gl);
        int g = 0;
        int c = 0;
        while (g < n) {
            if (Evidence.GlGet(gl, g, Evidence.ChPage()) == page) {
                c += 1;
            }
            g += 1;
        }
        return c;
    }
    internal static int CtRealRows(int emonT, byte[] rows) {
        // real.txt: `path page digest glyphs`. The file is one of corpus/ (not committed):
        // the digest of the page's glyph stream and its glyph count are what emon made of it
        // when pdfminer.six agreed, and must not change.
        emon.Port.Cells ar = emon.Port.NewCells();
        emon.Port.Cells dc = emon.Port.NewCells();
        emon.Port.Cells a = emon.Port.NewCells();
        emon.Port.Cells b = emon.Port.NewCells();
        emon.Port.Cells st = emon.Port.NewCells();
        emon.Port.Cells cx = emon.Port.NewCells();
        emon.Port.Cells ox = emon.Port.NewCells();
        emon.Port.Cells cs = emon.Port.NewCells();
        emon.Port.Cells @out = emon.Port.NewCells();
        emon.Port.Cells f0 = emon.Port.NewCells();
        emon.Port.Cells f1 = emon.Port.NewCells();
        emon.Port.Cells f2 = emon.Port.NewCells();
        emon.Port.Cells f3 = emon.Port.NewCells();
        emon.Port.Cells gl = emon.Port.NewCells();
        emon.Port.Cells et = emon.Port.NewCells();
        emon.Port.Cells mk = emon.Port.NewCells();
        emon.Port.Cells fnt = emon.Port.NewCells();
        emon.Port.Cells pg = emon.Port.NewCells();
        emon.Port.Cells wd = emon.Port.NewCells();
        emon.Port.Cells ln = emon.Port.NewCells();
        int n = emon.Port.BlobLen(rows);
        int pos = 0;
        int line = 0;
        int e = 0;
        int t1 = 0;
        int t2 = 0;
        int t3 = 0;
        int page = 0;
        int rowsn = 0;
        while (pos < n) {
            line += 1;
            e = CtNl(rows, pos);
            if ((pos < e) && (emon.Port.BlobU8(rows, pos) != 35)) {
                t1 = CtTab(rows, pos, e);
                t2 = CtTab(rows, t1 + 1, e);
                t3 = CtTab(rows, t2 + 1, e);
                page = CtDec(rows, t1 + 1, t2);
                rowsn += 1;
                emon.Testport.AssertEqAt(CtRun(emon.Port.SrcOfBlob(emon.Testport.TestFileSpan(rows, pos, t1)), ar, dc, a, b, st, cx, ox, cs, @out, f0, f1, f2, f3, gl, et, mk, fnt, pg, wd, ln), 0, "the file ran", line);
                emon.Testport.AssertEqAt(Contentrows.CrDigest(gl, et, page), CtDec(rows, t2 + 1, t3), "digest of the page's text", line);
                emon.Testport.AssertEqAt(CtCountPage(gl, page), CtDec(rows, t3 + 1, e), "glyphs on the page", line);
            }
            pos = e + 1;
        }
        return rowsn;
    }
