    internal static int CtCopy(byte[] b, emon.Port.Cells c) {
        int n = emon.Port.BlobLen(b);
        int i = 0;
        emon.Port.CellsDrop(c, 0);
        while (i < n) {
            emon.Port.CellsPush(c, emon.Port.BlobU8(b, i));
            i += 1;
        }
        return n;
    }
    internal static int CtFuzzFile(int emonT, byte[] bytes, int iters, int cutStep) {
        // Flip 1-6 random bytes `iters` times, and cut the file at every `cut-step` bytes; run each.
        // Nothing is asserted but that no run faults, on any target, whatever it says.
        emon.Port.Cells ar = emon.Port.NewCells();
        emon.Port.Cells dc = emon.Port.NewCells();
        emon.Port.Cells a = emon.Port.NewCells();
        emon.Port.Cells b = emon.Port.NewCells();
        emon.Port.Cells st = emon.Port.NewCells();
        emon.Port.Cells cx = emon.Port.NewCells();
        emon.Port.Cells ox = emon.Port.NewCells();
        emon.Port.Cells cs = emon.Port.NewCells();
        emon.Port.Cells @out = emon.Port.NewCells();
        emon.Port.Cells f0 = emon.Port.NewCells();
        emon.Port.Cells f1 = emon.Port.NewCells();
        emon.Port.Cells f2 = emon.Port.NewCells();
        emon.Port.Cells f3 = emon.Port.NewCells();
        emon.Port.Cells gl = emon.Port.NewCells();
        emon.Port.Cells et = emon.Port.NewCells();
        emon.Port.Cells mk = emon.Port.NewCells();
        emon.Port.Cells fnt = emon.Port.NewCells();
        emon.Port.Cells pg = emon.Port.NewCells();
        emon.Port.Cells wd = emon.Port.NewCells();
        emon.Port.Cells ln = emon.Port.NewCells();
        emon.Port.Cells work = emon.Port.NewCells();
        emon.Port.Cells rng = emon.Port.NewCells();
        int n = emon.Port.BlobLen(bytes);
        int it = 0;
        int k = 0;
        int flips = 0;
        int cut = 0;
        int runs = 0;
        int at = 0;
        Splitmix.SmSeed(rng, 4242);
        while (it < iters) {
            CtCopy(bytes, work);
            flips = 1 + Splitmix.SmBelow(rng, 6);
            k = 0;
            while (k < flips) {
                at = Splitmix.SmBelow(rng, n);
                emon.Port.CellsSet(work, at, Splitmix.SmBelow(rng, 256));
                k += 1;
            }
            CtRun(emon.Port.SrcOfCells(work), ar, dc, a, b, st, cx, ox, cs, @out, f0, f1, f2, f3, gl, et, mk, fnt, pg, wd, ln);
            runs += 1;
            it += 1;
        }
        cut = cutStep;
        while (cut < n) {
            CtCopy(bytes, work);
            emon.Port.CellsDrop(work, cut);
            CtRun(emon.Port.SrcOfCells(work), ar, dc, a, b, st, cx, ox, cs, @out, f0, f1, f2, f3, gl, et, mk, fnt, pg, wd, ln);
            runs += 1;
            cut += cutStep;
        }
        return runs;
    }
